let modalCallback=null,lastFocus=null;
function modal(title,subtitle,body,onSave=null,wide=false,saveLabel='Save changes'){lastFocus=document.activeElement;modalCallback=onSave;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="modal-close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="dialog-form"><div class="modal-body">${body}<p class="field-error" id="form-error" role="alert"></p></div><div class="modal-actions"><button type="button" class="btn" data-action="close">${onSave?'Cancel':'Close'}</button>${onSave?`<button class="btn primary" type="submit">${icon('check')}${saveLabel}</button>`:''}</div></form></section></div>`;$('#overlay').querySelector('input,select,textarea,button')?.focus();document.body.style.overflow='hidden';paginateTables($('#overlay'));}
