async function childDetail(id){if(liveReview){globalThis.__massDataLoading=true;render();try{await globalThis.__massEnsureView?.('student-detail');}catch(error){toast(error.message);return;}finally{globalThis.__massDataLoading=false;render();}}const s=db.students.find(s=>s.id===id);if(!s)return toast('This student is no longer in your authorized roster.');const r=stats(s);modal(s.name,`${centreName(s.centre)} · ${s.shift} · Grade ${s.grade}`,`<div class="detail-grid"><div><small>Attendance · ${monthName()}</small><strong>${r.p} days</strong>${badge(r.missing?'Incomplete':attendanceDisplayBand(r.p).label,r.missing?'muted':attendanceDisplayBand(r.p).tone)}</div><div><small>Activity participation</small><strong>${r.act} / ${r.held}</strong>${badge(activityDisplayBand(r.act,r.unknown).label,activityDisplayBand(r.act,r.unknown).tone)}</div><div><small>${state.exam} combined test</small><strong>${r.score??'—'} <small>/ ${r.maxMarks}${r.sample?' sample':''}</small></strong>${badge(recordedBand(r).label,recordedBand(r).tone)}</div></div><div style="margin:20px 0">${engagement(r)}<p class="chart-note">${r.missing} unmarked attendance entries · ${r.unknown} activity records missing.</p></div>${String(s.grade)==='10'?`<h3>Class 10 board exam</h3><p>Passed Class 10 board exam? <strong>${esc(s.boardPassed||'Not entered')}</strong></p>`:''}<h3>CAC attendance status · ${monthName()}</h3><p>${badge(dropoutStatus(s).status,dropoutStatus(s).tone)} ${esc(dropoutStatus(s).reason)}</p><h3>Exam history</h3>${['F1','F2','F3','F4'].map(ex=>bar(ex+' / '+scoreInfo(s,ex).maxMarks,db.scores[id]?.[ex]??null,scoreInfo(s,ex).maxMarks,'blue')+(db.scores[id]?.[ex]==null?'<small>Not recorded</small>':'')).join('')}<div class="divider"></div><h3>Teacher’s assessment notes</h3><p class="chart-note">${r.date?fmtDate(r.date):'Exam date not recorded'} · ${esc(r.performance||'No performance remarks recorded.')}</p><h3>Main challenge</h3><p class="chart-note">${esc(s.challenge||'Not recorded.')}</p><div class="divider"></div><p>${esc(db.followups[id]?.note||'No follow-up note yet.')}</p><div style="display:flex;gap:10px;margin-top:20px"><button class="btn" type="button" data-edit-child="${id}">${icon('people')}Edit profile</button><button class="btn dark" type="button" data-followup="${id}">${icon('flag')}Follow-up note</button></div>`,null,true);}
function editChild(id){const student=db.students.find(s=>s.id===id),s=student||{name:'',centre:scope()[0]?.id,grade:state.grade||'1',gender:'Girl',shift:state.shift||'Morning',enrolled:TODAY,challenge:''};modal(id?'Edit student profile':'Add student','Create the profile once. Attendance, activities and assessments use the same student ID.',`<div class="form-grid">${field('Full name','name',s.name,'text','full')}${drop('Centre / village','centre',scope().map(c=>[c.id,c.name]),s.centre)}${drop('Shift','shift',['Morning','Evening'],s.shift)}${drop('Grade','grade',Array.from({length:10},(_,i)=>String(i+1)),s.grade)}${drop('Gender','gender',['Girl','Boy'],s.gender)}<label class="field full" id="board-result-field" ${String(s.grade)==='10'?'':'hidden'}><span>Passed Class 10 board exam?</span><select name="boardPassed" ${String(s.grade)==='10'?'':'disabled'}><option value="">Select result</option>${['Yes','No'].map(v=>`<option value="${v}" ${s.boardPassed===v?'selected':''}>${v}</option>`).join('')}</select><small>Leave blank until the board-exam result is known.</small></label>${field('Enrolment date','enrolled',s.enrolled,'date','full')}${drop('Enrolment status','enrolmentStatus',['Active','CAC dropout','Left programme'],s.enrolmentStatus||(s.active===false?'Left programme':'Active'))}${field('Exit date (required when leaving)','exitDate',s.exitDate||'','date')}<label class="field full"><span>Main challenge (optional teacher note)</span><textarea name="challenge" rows="3">${esc(s.challenge||'')}</textarea></label>${id?'':`<label class="field-checkbox field full"><input type="checkbox" name="differentStudent"> If a possible match is found, I have checked that this is a different student.</label>`}</div><p class="form-help">Possible matches are checked by name, centre and grade. Records are never merged automatically. Keep personal notes relevant to learning and attendance.</p>`,f=>{if(!f.name?.trim()||!f.enrolled)throw Error('Enter a name and enrolment date.');if(f.enrolled>TODAY)throw Error('Enrolment date cannot be in the future.');if(!scope().some(c=>c.id===f.centre))throw Error('Choose an assigned centre.');const normal=n=>n.trim().toLowerCase().replace(/\s+/g,' '),match=db.students.find(c=>c.id!==id&&normal(c.name)===normal(f.name)&&c.centre===f.centre&&c.grade===f.grade);if(match&&!f.differentStudent)throw Error('Possible match: '+match.name+' ('+match.id+'). Check Student Profile first. If this is a different child, tick the confirmation above.');delete f.differentStudent;if(f.grade==='10'&&!['','Yes','No'].includes(f.boardPassed??''))throw Error('Choose Yes or No, or leave the board result blank.');if(f.enrolmentStatus!=='Active'&&(!f.exitDate||f.exitDate<f.enrolled||f.exitDate>TODAY))throw Error('For a student who has left, enter an exit date between enrolment and today.');if(f.enrolmentStatus==='Active'&&f.exitDate)throw Error('Clear the exit date for an active student.');f.active=f.enrolmentStatus==='Active';f.name=f.name.trim();if(id)Object.assign(s,f);else{const nextId='CAC-'+String(Math.max(...db.students.map(x=>+x.id.slice(4)),0)+1).padStart(3,'0');db.students.push({id:nextId,...f,note:''});db.scores[nextId]={F1:null,F2:null,F3:null,F4:null};}Object.assign(state,{centre:state.role==='Teacher'?'':f.centre,shift:f.shift,grade:'',gender:'',query:''});persist('Student profile saved · shared across records');});}

function followup(id){const s=db.students.find(s=>s.id===id),f=db.followups[id]||{};modal('Follow-up note',`${s.name} · ${centreName(s.centre)}`,`<div class="form-grid">${drop('Status','status',['To follow up','In progress','Completed'],f.status||'To follow up')}${field('Next contact date (optional)','date',f.date||'','date')}<label class="field full"><span>What needs attention?</span><textarea name="note" rows="4" required>${esc(f.note||'')}</textarea></label></div><p class="form-help">Record an observation or action. CAC dropout uses zero attendance for one full completed month with complete records; it does not establish school dropout or automatically close enrolment.</p>`,v=>{if(!v.note.trim())throw Error('Add a short follow-up note.');db.followups[id]={...v,updated:new Date().toISOString()};persist('Follow-up saved');});}
function enterMarks(){const list=children(),key=[state.exam,state.centre||'all',state.shift||'both'].join('|'),batch=db.assessmentBatches[key]||{};modal(`Enter ${state.exam} marks`,'One row per student · one date for the group',`<div class="form-grid">${field('Exam date','batchDate',batch.date||'','date','full')}</div><p class="form-help">Configured maximum marks are read-only. Zero is a score. Absent and not entered stay separate. Subject sections and maxima must be agreed with MASS before adding subject scores.</p><div class="table-scroll"><table><thead><tr><th>Student</th><th>Grade / shift</th><th>Status</th><th>Marks</th><th>Maximum</th></tr></thead><tbody>${list.map(c=>{const r=scoreInfo(c);return `<tr><td>${esc(c.name)}<div class="subtext">${c.id}</div></td><td>${c.grade} · ${c.shift}</td><td>${drop('Status for '+c.name,'status_'+c.id,['Recorded','Absent','Not entered'],r.status)}</td><td>${field('Marks for '+c.name,'score_'+c.id,r.score??'','number')}</td><td>${r.maxMarks}${r.sample?' (sample)':''}</td></tr>`;}).join('')}</tbody></table></div><label class="field full"><span>Overall assessment comment (optional)</span><textarea name="overall" rows="3">${esc(batch.comment||'')}</textarea></label>`,f=>{const updates=[];for(const c of list){const r=scoreInfo(c),v=f['score_'+c.id],status=f['status_'+c.id],changed=v!==(r.score===null?'':String(r.score))||status!==r.status||!!f.batchDate;if(!changed)continue;if(status==='Recorded'&&(v===''||!Number.isInteger(+v)||+v<0||+v>r.maxMarks))throw Error('Enter whole marks from 0 to '+r.maxMarks+' for '+c.name+'.');if(status!=='Recorded'&&v!=='')throw Error('Clear marks for '+c.name+' when '+status+'.');const date=f.batchDate||r.date;if(status==='Recorded'&&!date)throw Error('Enter the group exam date.');if(date>TODAY)throw Error('Exam date cannot be in the future.');updates.push({c,v,status,date,r});}for(const {c,v,status,date,r} of updates){db.scores[c.id]??={};db.scores[c.id][state.exam]=status==='Recorded'?+v:null;db.assessmentDetails[c.id+'|'+state.exam]={...db.assessmentDetails[c.id+'|'+state.exam],year:'2026–27',maxMarks:r.maxMarks,status,date};}db.assessmentBatches[key]={date:f.batchDate||batch.date||'',comment:f.overall};persist('Assessment saved');},true,'Save marks');}
function eventEdit(id){activitySession(id);}
function sessionEntry(){modal('Update CAC session','One planned session per centre, shift and date.',`<div class="form-grid">${drop('Centre','centre',scope().map(c=>[c.id,c.name]),scope()[0]?.id)}${drop('Shift','shift',['Morning','Evening'],state.shift||'Morning')}${field('Session date','date',state.date,'date')}${drop('Status','status',['Planned','Held','Cancelled'],'Held')}</div><p class="form-help">A child marked present does not automatically mark a session held.</p>`,f=>{if(!scope().some(c=>c.id===f.centre))throw Error('Choose an assigned centre.');if(!f.date)throw Error('Choose a session date.');if(f.status==='Held'&&f.date>TODAY)throw Error('Future sessions must remain planned.');const found=db.sessions.find(r=>r.centre===f.centre&&r.shift===f.shift&&r.date===f.date);if(found)Object.assign(found,f);else db.sessions.push(f);persist('Session status saved');});}
function newActivity(){activitySession();}
function activityPlanReference(){if(liveReview)return section('Activity plan reference','Confirmed general cadence', '<p class="chart-note">Four activities per centre per month, shared across the morning and evening shifts. Do not count the same centre event twice. Monthly meetings happen once per centre per month, also shared across both shifts. Record student participation separately from classroom attendance. Exact dates and delivered events still need to be recorded.</p>');return `<details class="card plan-reference" style="margin:22px 0"><summary>Annual activity plan · field photo reference</summary><p class="chart-note">The photographed plan runs May 2026–April 2027. Planned items below do not count as held events or child participation.</p><div class="table-scroll"><table><thead><tr><th>Planned item</th><th>Calendar reference</th><th>System entry</th></tr></thead><tbody><tr><td>CAC classes</td><td>24 days/month, June–April</td><td>Confirm actual held centre/shift days</td></tr><tr><td>Cultural activities</td><td>2/month, June–April</td><td>First and third Saturday; editable name</td></tr><tr><td>Sports activities</td><td>2/month, June–April</td><td>Second and fourth Saturday; editable name</td></tr><tr><td>Important days</td><td>Named observances vary by month</td><td>Add as separate Important day events</td></tr><tr><td>Other annual-plan items</td><td>Jatha, orientation, child-list/baseline update, parents’ meetings, children’s parliament, adolescent girls’ meetings and youth-group meetings</td><td>Reference only; tracking scope must be agreed separately</td></tr></tbody></table></div></details>`;}
function activityEntry(){const ev=activityEvents();modal('Choose an activity','Open an activity to record or correct each child’s participation.',`<div class="attention-list">${ev.map(e=>`<div class="attention-item"><div style="flex:1"><strong>${centreHtml(e.centre)} · ${esc(e.name)}</strong><p>${fmtDate(e.date)} · ${e.category} · ${e.status}</p></div><button type="button" class="btn tiny" data-event="${e.id}">Open →</button></div>`).join('')||empty('No activities match this selection.')}</div>`,null,true);}
function newVisit(id){const existing=db.visits.find(v=>v.id===id);modal(existing?'Edit centre visit':'Record a centre visit','Two morning and two evening visits per centre, each month.',`<div class="form-grid">${drop('Centre','centre',scope().map(c=>[c.id,c.name]),existing?.centre||state.centre||scope()[0]?.id)}${drop('Shift','shift',['Morning','Evening'],existing?.shift||'Morning')}${field('Visit date','date',existing?.date||TODAY,'date')}${drop('Status','status',['Completed','Planned'],existing?.status||'Completed')}<label class="field full"><span>Centre feedback</span><textarea rows="3" name="feedback" required>${esc(existing?.feedback||'')}</textarea></label><label class="field full"><span>Next action</span><textarea rows="2" name="action">${esc(existing?.action||'')}</textarea></label></div>`,f=>{if(!f.date||!f.feedback.trim())throw Error('Add the visit date and centre feedback.');if(f.status==='Completed'&&f.date>TODAY)throw Error('A future visit must be planned, not completed.');const c=centres.find(c=>c.id===f.centre);if(!scope().some(x=>x.id===f.centre))throw Error('Choose an assigned centre.');if(existing)Object.assign(existing,{officer:c.officer,...f});else db.visits.push({id:'V-'+Date.now(),officer:c.officer,...f});persist('Visit saved');});}
function editMorarji(id){const historic=db.morarjiHistory.find(r=>r.s.id===id),r=db.morarji[id]||historic,s=db.students.find(s=>s.id===id)||historic?.s;modal('Morarji follow-up',`${s.name} · ${r.cohort} cohort`, `<div class="form-grid">${field('Training days attended','trainingDays',r.trainingDays,'number')}${drop('Applied for exam?','applied',[['null','Unknown'],['true','Yes'],['false','No']],String(r.applied))}${drop('Took the exam?','took',[['null','Unknown'],['true','Yes'],['false','No']],String(r.took))}${drop('Exam result','result',['Pending','Passed','Not passed','Not applied'],r.result)}${drop('Selected?','selected',[['null','Unknown'],['true','Yes'],['false','No']],String(r.selected))}${drop('Admitted?','admitted',[['null','Unknown'],['true','Yes'],['false','No']],String(r.admitted))}${drop('Scholarship receipt','scholarship',['Not recorded','Pending','Received'],r.scholarship,'full')}</div>`,f=>{if(f.trainingDays!==''&&(!Number.isInteger(+f.trainingDays)||+f.trainingDays<0))throw Error('Training days must be a non-negative whole number.');if(f.applied==='false'&&f.took==='true')throw Error('Check the application and exam-attendance entries.');if(f.took!=='true'&&['Passed','Not passed'].includes(f.result))throw Error('A pass/fail result requires the child to have taken the exam.');if(f.admitted==='true'&&f.selected!=='true')throw Error('Check selection before recording admission.');Object.assign(r,f,{trainingDays:f.trainingDays===''?null:+f.trainingDays,applied:f.applied==='null'?null:f.applied==='true',took:f.took==='null'?null:f.took==='true',selected:f.selected==='null'?null:f.selected==='true',admitted:f.admitted==='null'?null:f.admitted==='true'});persist('Morarji follow-up saved');});}
function editGuidance(id){const r=db.guidance.find(g=>g.id===id);modal('Career guidance follow-up',`${r.name} · ${centreName(r.centre)}`,`<div class="form-grid">${field('Follow-up date','followup',r.followup,'date')}${drop('Contact status','contact',['Contacted','Not contacted'],r.contact)}${drop('Destination','destination',['Unknown','Class 11 — Arts','Class 11 — Science','Class 12','ITI — Electrical','Diploma course'],r.destination,'full')}${drop('Evidence source','verification',['Self-reported','Verified admission'],r.verification,'full')}</div>`,f=>{if(f.contact==='Not contacted'&&f.destination!=='Unknown')throw Error('Uncontacted participants should remain Unknown until a destination is reported.');if(!f.followup||f.followup>TODAY)throw Error('Enter a follow-up date on or before today.');Object.assign(r,f);persist('Career follow-up saved');});}
let removalUndo=null,recordKind='Attendance';
function managedRecords(kind=recordKind){if(state.role==='Leadership')return [];const permitted=centres.filter(c=>state.role==='Teacher'?c.id==='C01':c.officer==='Meera').map(c=>c.id),students=db.students.filter(s=>permitted.includes(s.centre)),ids=new Set(students.map(s=>s.id)),out=[],add=(key,label,detail)=>out.push({key,label,detail});
if(kind==='Students')students.forEach(s=>add(s.id,s.name,s.id+' · '+centreName(s.centre)+' · '+s.shift));
if(kind==='Attendance')Object.entries(db.attendance).forEach(([key,v])=>{const [id,date]=key.split('|'),s=students.find(s=>s.id===id);if(s&&date===state.date)add(key,s.name,date+' · '+centreName(s.centre)+' · '+v);});
if(kind==='Exam results')students.forEach(s=>['F1','F2','F3','F4'].forEach(ex=>{const r=scoreInfo(s,ex);if(r.score!==null||r.status!=='Not entered')add(s.id+'|'+ex,s.name,ex+' · '+r.status+' · '+(r.score??'—')+' / '+r.maxMarks);}));
if(kind==='Activities')db.events.filter(e=>permitted.includes(e.centre)).forEach(e=>add(e.id,e.name,e.date+' · '+centreName(e.centre)+' · '+e.status));
if(kind==='CAC sessions')db.sessions.filter(e=>permitted.includes(e.centre)).forEach(e=>add([e.centre,e.shift,e.date].join('|'),centreName(e.centre),e.date+' · '+e.shift+' · '+e.status));
if(kind==='Visits'&&state.role==='Cluster Officer')db.visits.filter(e=>permitted.includes(e.centre)).forEach(e=>add(e.id,centreName(e.centre),e.date+' · '+e.shift+' · '+e.status));
if(kind==='Morarji')morarjiRows(true).forEach(r=>{if(permitted.includes(r.s.centre))add(r.s.id,r.s.name,r.cohort+' · '+r.result);});
if(kind==='Follow-up notes')Object.keys(db.followups).filter(id=>ids.has(id)).forEach(id=>add(id,students.find(s=>s.id===id).name,db.followups[id].note));return out;}
function manageRecords(){if(state.role==='Leadership')return;const kinds=['Attendance','Exam results','Activities','CAC sessions','Students','Morarji','Follow-up notes',...(state.role==='Cluster Officer'?['Visits']:[])];if(!kinds.includes(recordKind))recordKind='Attendance';const rows=managedRecords();modal('Correct / remove entries','Only your assigned centres · all records except attendance, which uses the selected date.',`<label class="field"><span>Record type</span><select id="record-kind">${kinds.map(k=>`<option ${k===recordKind?'selected':''}>${k}</option>`).join('')}</select></label>${recordKind==='Attendance'?`<label class="field"><span>Attendance date</span><input type="date" id="record-date" value="${state.date}" max="${TODAY}"></label>`:''}<p class="form-help">Removal makes an entry unrecorded, never absent or zero. You can undo the last removal until another change is saved or the page is reloaded. Remove a student only if the profile was entered by mistake; use enrolment status for a genuine exit.</p><div class="table-scroll"><table><thead><tr><th>Record</th><th>Details</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.detail)}</td><td><button type="button" class="btn tiny" data-record-edit="${esc(r.key)}">Edit</button> <button type="button" class="btn tiny remove-button" data-record-remove="${esc(r.key)}">Remove</button></td></tr>`).join('')}</tbody></table>${rows.length?'':empty('No saved entries in this selection.')}</div>`,null,true);}
function removeRecord(key){const record=managedRecords().find(r=>r.key===key);if(!record)return;const kind=recordKind,detail=kind==='Students'?'This removes the profile and its attendance, exam results, activity participation, follow-up note and current Morarji link. Use enrolment status instead if the student has actually left.':kind==='Activities'?'This removes the activity session and its child participation entries.':kind==='CAC sessions'?'This removes only the session record. Existing child attendance stays unchanged and must be reviewed separately.':'Only this saved record will be removed. Missing is not absence, failure or zero.';modal('Remove this entry?',record.label+' · '+record.detail,`<p>${esc(detail)}</p><p>You can undo this removal before another change is saved or this page is reloaded.</p>`,()=>{if(!managedRecords(kind).some(r=>r.key===key))throw Error('This record is no longer available in your assigned centres.');const snapshot=JSON.stringify(db);if(kind==='Students'){db.students=db.students.filter(s=>s.id!==key);for(const bucket of ['attendance','participation','assessmentDetails'])for(const k of Object.keys(db[bucket]||{}))if(k.startsWith(key+'|'))delete db[bucket][k];delete db.scores[key];delete db.followups[key];delete db.morarji[key];}if(kind==='Attendance')delete db.attendance[key];if(kind==='Exam results'){const [id,ex]=key.split('|');delete db.scores[id][ex];delete db.assessmentDetails[key];}if(kind==='Activities'){db.events=db.events.filter(e=>e.id!==key);for(const k of Object.keys(db.participation))if(k.endsWith('|'+key))delete db.participation[k];}if(kind==='CAC sessions')db.sessions=db.sessions.filter(e=>[e.centre,e.shift,e.date].join('|')!==key);if(kind==='Visits')db.visits=db.visits.filter(e=>e.id!==key);if(kind==='Morarji'){delete db.morarji[key];db.morarjiHistory=db.morarjiHistory.filter(r=>r.s.id!==key);}if(kind==='Follow-up notes')delete db.followups[key];persist('Entry removed · use Undo last removal to restore');removalUndo={snapshot,role:state.role,savedAt:db.lastSaved};},false,'Remove entry');}
function undoRemoval(){if(!removalUndo||state.role!==removalUndo.role||db.lastSaved!==removalUndo.savedAt){removalUndo=null;toast('Undo is unavailable after another saved change or role switch.');render();return;}db=JSON.parse(removalUndo.snapshot);removalUndo=null;persist('Removed entry restored');render();}
function editManagedRecord(key){if(!managedRecords().some(r=>r.key===key))return;const [id,ex]=key.split('|');if(recordKind==='Students')return editChild(key);if(recordKind==='Exam results'){state.centre='';state.shift='';state.grade='';state.gender='';state.query='';state.studentIdQuery='';return editLearningRow(id);}if(recordKind==='Activities')return eventEdit(key);if(recordKind==='Visits')return newVisit(key);if(recordKind==='Morarji')return editMorarji(key);if(recordKind==='Follow-up notes')return followup(key);if(recordKind==='Attendance')return modal('Correct attendance',key,drop('Attendance code','code',['P','A','H'],db.attendance[key]),f=>{db.attendance[key]=f.code;persist('Attendance corrected');});if(recordKind==='CAC sessions'){const r=db.sessions.find(e=>[e.centre,e.shift,e.date].join('|')===key);modal('Correct CAC session',centreName(r.centre)+' · '+r.shift+' · '+r.date,drop('Session status','status',['Planned','Held','Cancelled'],r.status),f=>{if(f.status==='Held'&&r.date>TODAY)throw Error('A future session cannot be held.');r.status=f.status;persist('Session corrected');});}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||state.role==='Leadership')return;if(b.dataset.recordRemove)removeRecord(b.dataset.recordRemove);else if(b.dataset.recordEdit)editManagedRecord(b.dataset.recordEdit);else if(b.dataset.action==='manage-records')manageRecords();else if(b.dataset.action==='undo-remove')undoRemoval();});
document.addEventListener('change',e=>{if(e.target.id==='record-kind'){recordKind=e.target.value;manageRecords();}if(e.target.id==='record-date'){if(!e.target.value||e.target.value>TODAY){toast('Choose a valid date on or before the sample date.');return;}state.date=e.target.value;manageRecords();}});
function guide(){if(publicReview)return modal('About this dashboard','Access approval pending.','<p>The original dashboard opens without login. Public live data publication is awaiting MASS approval. Personal data and operational changes remain protected by verified authorization and server-enforced centre permissions. No demo values are substituted.</p>');if(liveReview)return modal('About this dashboard','MASS Children’s Activity Centres dashboard.',`<div class="help-grid"><div class="help-item"><h3>Your access</h3><p>The dashboard shows only the roles and centres assigned to your authenticated account. Saves and corrections use server-enforced permissions and revision checks.</p></div><div class="help-item"><h3>Reporting rules</h3><p>Attendance uses Present ÷ recorded classroom attendance, where L means Leave. H, MM and historical WO are excluded. Historical L remains in the denominator. Assessments use four April–March rounds with a maximum of 25 marks.</p></div><div class="help-item"><h3>Data coverage</h3><p>Missing records remain unknown. Historical assessment dates, delivery, donor validity, and programme outcomes are never inferred.</p></div></div><div class="divider"></div><button type="button" class="btn primary" data-action="export-explain">${icon('download')}Export current report</button>`,null,true);modal('About this prototype','A first interactive design for MASS — not a live student database.',`<div class="help-grid"><div class="help-item"><h3>Initial release</h3><p>Career Guidance is retained for later and hidden from the initial navigation.</p><button type="button" class="btn" data-action="later-modules">${state.laterModules?'Use initial-release navigation':'Preview later modules'}</button><h3>Three working views</h3><p>Teacher: own centre, both shifts. Cluster officer: assigned centres. Leadership: all centres and donor aggregates. The role switch is for preview; production permissions need a backend.</p></div><div class="help-item"><h3>One connected experience</h3><p>Attendance, activities, marks and follow-ups update the same records. Changes save in this browser and update charts immediately. They do not sync to other users.</p></div><div class="help-item"><h3>Confirmed engagement rule</h3><p>More than 20 days present AND more than two activities. Green is good engagement, not an award. Missing records remain visible.</p></div><div class="help-item"><h3>PM review needed</h3><p>Real combined-test maximum; 0–8 band label; actual operating-day calendar and holiday handling; definition of low activity participation; donor funding dates and access; correction audit/approval policy.</p></div></div><div class="divider"></div><h3>Attendance bands</h3><p class="chart-note">Below 15 low · 15 average · 16–20 good · 21–25 very good. Monthly sample calendar: 24 non-Sunday operating days. October is month-to-date.</p><h3>Activities</h3><p class="chart-note">Four Saturdays: cultural on the first and third, sports on the second and fourth. “Below two” is a provisional low-participation flag for review, not an agreed award rule.</p><div class="divider"></div><button type="button" class="btn primary" data-action="export">${icon('download')}Export current summary</button><p class="form-help">All child, officer and donor mappings here are fictional sample records. Do not enter real personal information in this preview.</p><button type="button" class="text-button" data-action="reset-demo">Reset sample records</button>`,null,true);}
function csvExport(){if(liveReview&&state.page==='overview'&&state.role!=='Leadership'&&db.summaryMonth!==state.month)throw Error('Wait for the authorized student summary to load before exporting.');
 if(publicReview)return toast('No approved public dataset is available to export.');
 let rows;
 if(liveReview&&state.page==='donor'){
  const months=(globalThis.__massReportingMonths||[]).map(value=>Array.isArray(value)?value[0]:value);
  const reviews=months.map(month=>scopedReview({...state,month})),current=scopedReview();
  if(reviews.some(value=>!value||value.pending)||!current||current.pending||current.unavailable)throw Error('Wait for the annual report to finish loading before downloading.');
  rows=[['Centre','Current donor association','Students at reporting date','Annual present','Annual absent','Annual leave','Annual attendance %','Loaded months','Academic year'],...scope().map(centre=>{const combined=combineMonthlyAttendance(reviews.map(review=>review&&!review.pending&&!review.unavailable?review.centres.find(value=>value.id===centre.id):null)),detail=current&&!current.pending&&!current.unavailable?current.centres.find(value=>value.id===centre.id):null;return [centre.name,centre.donor||'Not associated',detail?.children??'Unknown',combined.loaded?combined.p:'Unknown',combined.loaded?combined.a:'Unknown',combined.loaded?combined.l:'Unknown',combined.percentage===null?'Unknown':combined.percentage.toFixed(1),combined.loaded,state.academicYear];})];
 }else if(liveReview&&globalThis.__massAggregateMode)rows=globalThis.__massAggregateExport(state,scope());
 else if((liveReview?globalThis.__massActualRole==='Leadership':state.role==='Leadership')||state.page==='donor')rows=[['Centre','Active children','Present student-days','Good engagement'],...scope().map(c=>{const t=totals(children().filter(s=>s.centre===c.id));return [c.name,t.rows.length,t.p,t.good];})];
 else rows=[['Name','Centre','Shift','Grade','Month','Present','Unmarked','Activities attended','Activity records missing',state.exam,'Good engagement'],...totals().rows.map(r=>[r.s.name,centreName(r.s.centre),r.s.shift,r.s.grade,state.month,r.p,r.missing,r.act,r.unknown,r.score??'',liveReview?'Unknown: colour boundaries pending':r.good?'Yes':'No'])];
 const a=document.createElement('a'),url=URL.createObjectURL(new Blob([rows.map(row=>row.map(safeCsvCell).join(',')).join('\r\n')],{type:'text/csv'}));a.href=url;a.download='MASS-'+(state.role==='Leadership'||state.page==='donor'?'centre-aggregate':'student-summary')+'-'+(state.page==='donor'?state.academicYear:state.month)+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Current selection exported');
}
