document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.action==='load-summary'){state.summaryExpanded=true;render();return;}if(b.dataset.profileSort){state.profileSort=profileSortChoice(state.profileSort,b.dataset.profileSort);render();return;}if(state.role==='Leadership'&&(b.dataset.child||b.dataset.editMarks||b.dataset.editChild||b.dataset.followup||b.dataset.event||b.dataset.morarji||b.dataset.guidance||b.dataset.mark))return;if(b.matches('a[data-action]'))e.preventDefault();if(b.dataset.profilePage!==undefined){state.profilePage=Math.max(0,Number(b.dataset.profilePage));render();return;}if(b.dataset.nav){navigate(b.dataset.nav);return;}if(b.dataset.gender){state.gender=state.gender===b.dataset.gender?'':b.dataset.gender;tablePages={};render();return;}if(b.dataset.centre){state.centre=b.dataset.centre;render();return;}if(b.dataset.year){state.morarjiYear=b.dataset.year;render();return;}if(b.dataset.child){childDetail(b.dataset.child);return;}if(b.dataset.editMarks){editLearningRow(b.dataset.editMarks);return;}if(b.dataset.editChild){editChild(b.dataset.editChild);return;}if(b.dataset.followup){followup(b.dataset.followup);return;}if(b.dataset.event){eventEdit(b.dataset.event);return;}if(b.dataset.morarji){editMorarji(b.dataset.morarji);return;}if(b.dataset.guidance){editGuidance(b.dataset.guidance);return;}if(b.hasAttribute('data-shift')){state.shift=b.dataset.shift;render();return;}if(b.dataset.mark){const [id,code]=b.dataset.mark.split('|');const s=db.students.find(s=>s.id===id);if(!children().some(x=>x.id===id)||state.date<s.enrolled)return toast('Attendance cannot be entered before enrolment.');if(db.attendance[id+'|'+state.date]===code)return;db.attendance[id+'|'+state.date]=code;persist(`${s.name.split(' ')[0]} · ${db.attendance[id+'|'+state.date]?'marked '+code:'entry cleared'} · saved`);render();return;}const action=b.dataset.action;if(!action)return;if(state.role==='Leadership'&&['open-daily','new-child','enter-marks','activity-entry','new-activity','session-entry','new-visit','new-morarji','new-guidance','mark-all','mark-all-absent','mark-holiday','save-default-attendance','save-guidance-feedback'].includes(action))return;switch(action){case 'collapse-nav':state.collapsed=!state.collapsed;render();break;case 'later-modules':state.laterModules=!state.laterModules;close();if(!state.laterModules&&state.page==='guidance')state.page='overview';render();break;case 'print-report':window.print();break;case 'new-morarji':newMorarji();break;case 'new-guidance':newGuidance();break;case 'menu':state.menu=!state.menu;render();break;case 'close':close();break;case 'guide':guide();break;case 'donor':navigate('donor');break;case 'open-morarji':navigate('morarji');break;case 'open-profiles':navigate('children');break;case 'retry-profiles':globalThis.__massProfilePages?.invalidate();render();break;case 'reset-morarji':state.centre='';state.morarjiYear='2025–26';render();break;case 'back-overview':navigate('overview');break;case 'open-daily':navigate('daily');break;case 'monthly-attendance':state.month=state.date.slice(0,7);navigate('attendance');break;case 'new-child':editChild();break;case 'enter-marks':enterMarks();break;case 'activity-entry':activityEntry();break;case 'new-activity':newActivity();break;case 'session-entry':sessionEntry();break;case 'new-visit':newVisit();break;case 'reset-filters':if(liveReview)Object.assign(state,resetPopulationFilters(state,globalThis.__massAcademicYears||[],TODAY));else Object.assign(state,{centre:'',shift:'',grade:'',gender:'',officer:'',donor:'',query:'',studentIdQuery:'',concerns:false,engagementFilter:'',month:TODAY.slice(0,7),exam:'F2',comparison:'F1|F2',fromExam:'F1',toExam:'F2'});render();break;case 'prev-date':case 'next-date':{const d=new Date(state.date+'T12:00:00');d.setDate(d.getDate()+(action==='prev-date'?-1:1));state.date=d.toISOString().slice(0,10);render();break;}case 'save-default-attendance':{const list=children().filter(s=>state.date>=s.enrolled);if(state.date>TODAY)return toast('Choose a date on or before today.');let count=0;for(const s of list)if(!db.attendance[s.id+'|'+state.date]){db.attendance[s.id+'|'+state.date]='P';count++;}persist(`${count} default Present entries saved; existing codes preserved`);render();break;}case 'mark-all':case 'mark-all-absent':case 'mark-holiday':{const code=action==='mark-all'?'P':action==='mark-all-absent'?'A':'H',list=children().filter(s=>state.date>=s.enrolled);modal(code==='P'?'Mark visible children present?':code==='A'?'Mark visible children absent?':'Mark this group on holiday?',`${list.length} children · ${fmtDate(state.date)}`,`<p>Existing entries for the children currently shown will change to <strong>${code==='P'?'Present':code==='A'?'Absent':'Holiday'}</strong>. You can correct individual records afterwards.</p>`,()=>{list.forEach(s=>db.attendance[s.id+'|'+state.date]=code);persist(`${list.length} attendance entries saved`);},false,'Confirm and save');break;}case 'save-guidance-feedback':db.guidanceFeedback=$('#guidance-feedback').value;persist('Teacher feedback saved');break;case 'export-explain':modal('Export current report',state.page==='donor'?'Downloads all centres matching the selected donor, academic year and centre filters.':'Downloads all matching rows in your current authorized selection, including rows on other pages.',`<p>Leadership and donor exports contain centre-level aggregate rows. Other authorized roles receive the currently filtered student summary when permitted. The download includes all filtered rows, not only the current table page. Missing or unavailable measures remain explicit and are never exported as zero.</p>`,()=>{csvExport();},false,'Download CSV');break;case 'export':try{csvExport();}catch{toast('The current authorized summary is still loading or unavailable. Retry after the data loads.');}break;case 'reset-demo':modal('Reset sample records?','This affects only this browser.',`<p>Your prototype edits will be replaced with the original fictional sample records.</p>`,()=>{db=seed();db.assessmentDetails={};db.assessmentBatches={};persist('Sample records reset');},false,'Reset sample records');break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-page-jump]'))return;if(el.matches('[data-profile-jump]')){const value=Number(el.value);if(Number.isInteger(value)&&value>=1&&value<=Number(el.max)&&state.profilePage!==value-1){state.profilePage=value-1;render();}return;}if(el.name==='grade'){const board=document.querySelector('#board-result-field');if(board){board.hidden=el.value!=='10';board.querySelector('select').disabled=el.value!=='10';}}if(el.name?.startsWith('status_')&&el.value!=='Recorded'){const score=document.querySelector('[name=\"score_'+el.name.slice(7)+'\"]');if(score)score.value='';}if(el.id==='role'){state.summaryExpanded=false;if(liveReview){if(!globalThis.__massOperationalRoles||globalThis.__massDataLoading||!globalThis.__massActualRoles?.includes(el.value)){el.value=state.role;return;}const previous=state.role,next=el.value;close();Object.assign(state,{role:next,page:'overview',centre:'',shift:'',grade:'',gender:'',donor:'',officer:'',query:'',studentIdQuery:'',concerns:false,engagementFilter:''});globalThis.__massDataLoading=true;globalThis.__massLoadingLabel=`Loading ${next} records…`;render();globalThis.__massSelectRole(next).then(()=>{globalThis.__massDataLoading=false;delete globalThis.__massLoadingLabel;if(globalThis.__massLiveReviewData){render();window.scrollTo(0,0);}}).catch(error=>{Object.assign(state,{role:previous,page:'overview',centre:'',shift:'',grade:'',gender:'',donor:'',officer:'',query:'',studentIdQuery:'',concerns:false,engagementFilter:''});globalThis.__massDataLoading=false;delete globalThis.__massLoadingLabel;if(globalThis.__massLiveReviewData)render();toast(error.message);});return;}close();Object.assign(state,{role:el.value,page:'overview',centre:'',shift:'',grade:'',gender:'',donor:'',officer:'',query:'',studentIdQuery:'',concerns:false,engagementFilter:''});render();window.scrollTo(0,0);}else if(el.dataset.filter){state[el.dataset.filter]=el.value;if(liveReview&&el.dataset.filter==='academicYear'){globalThis.__massDataLoading=true;render();globalThis.__massSelectAcademicYear(el.value).then(year=>{state.month=year.starts_on.slice(0,7);state.date=year.starts_on;if(globalThis.__massLiveReviewData)render();}).catch(error=>{state.academicYear=db.academicYear;globalThis.__massDataLoading=false;if(globalThis.__massLiveReviewData)render();toast(error.message);});return;}if(liveReview)Object.assign(state,reconcilePopulationFilters(db.students,centres,state,{profileReadable:!globalThis.__massAggregateMode,changed:el.dataset.filter}));if(el.dataset.filter==='comparison')[state.fromExam,state.toExam]=el.value.split('|');tablePages={};render();if(liveReview&&['month','officer'].includes(el.dataset.filter))void globalThis.__massLoadVisitMonth?.(state.month,state.officer||null);}else if(el.id==='attendance-date'){if(!el.value||el.value>TODAY){toast('Select a date on or before today.');render();return;}if(liveReview){const y=(globalThis.__massAcademicYears||[]).find(y=>y.starts_on<=el.value&&el.value<y.ends_before);if(!y){toast('No approved academic year covers this date.');render();return;}state.date=el.value;state.month=el.value.slice(0,7);if(y.id!==db.academicYear){state.academicYear=y.id;globalThis.__massDataLoading=true;render();globalThis.__massSelectAcademicYear(y.id).then(()=>{if(globalThis.__massLiveReviewData)render();}).catch(error=>toast(error.message));return;}}else{state.date=el.value;state.month=el.value.slice(0,7);}render();}else if(el.id==='concerns'){state.concerns=el.checked;render();}});
document.addEventListener('input',e=>{if(e.target.name?.startsWith('score_')&&e.target.value!==''){const status=document.querySelector('[name=\"status_'+e.target.name.slice(6)+'\"]');if(status)status.value='Recorded';}if(['student-search','student-id-search'].includes(e.target.id)){const id=e.target.id,pos=e.target.selectionStart;state[id==='student-id-search'?'studentIdQuery':'query']=e.target.value;const y=window.scrollY;render();$('#'+id)?.focus();$('#'+id)?.setSelectionRange(pos,pos);window.scrollTo(0,y);}});
document.addEventListener('submit',async e=>{if(e.target.id!=='dialog-form')return;e.preventDefault();const form=e.target;if(form.dataset.saving)return;form.dataset.saving='true';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;const values=Object.fromEntries(new FormData(form));const locked=form.dataset.attendanceRegister==='true'?[...form.querySelectorAll('input,select,button')].filter(n=>!n.disabled):[];locked.forEach(n=>n.disabled=true);try{if(await modalCallback?.(values)===false)return;delete form.dataset.saving;close();render();}catch(err){const target=form.querySelector('#form-error');if(target)target.textContent=err.message;}finally{delete form.dataset.saving;locked.forEach(n=>n.disabled=false);if(submit)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-page-jump],[data-profile-jump]')){e.preventDefault();e.target.dispatchEvent(new Event('change',{bubbles:true}));return;}if(e.key==='Escape'){close();if(state.menu){state.menu=false;render();}}if(e.key==='Tab'&&$('#overlay').children.length){const nodes=[...$('#overlay').querySelectorAll('button,a,input,select,textarea')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
