  if((el.dataset.participation!==undefined||el.dataset.participationAll!==undefined)&&el.closest('form')?.dataset.liveParticipation==='true')return;
  if(action==='visit-trends'){event.preventDefault();event.stopImmediatePropagation();void globalThis.__massLoadVisitTrends?.(state.officer||null);return;}
  const mutation=/^(new-|enter-|open-daily|mark-|session-entry|activity-entry|save-|manage-records|reset-demo|undo-remove|default-present|edit-)/.test(action)||['mark','participation','participationAll','recordEdit','recordRemove','assessmentGroup','editChild','editMarks','followup','morarji','guidance','event','visitEdit','visitHistory','activityEdit','attendanceEdit','recordHistory'].some(k=>el.dataset[k]!==undefined);
  if(!mutation&&!['authorize-staff','sign-out','prev-date','next-date'].includes(action))return;
